package cli

import (
	"fmt"
	"path"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/adapter"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// sharedSkillsDir is the directory 17 of 23 surveyed harnesses read skills
// from, and the reason most harnesses need no adapter at all.
//
// A skill installs here once and is visible to every harness that reads it,
// rather than being copied into one directory per declared harness — which is
// what ADR 0002 chose and what makes the `harnesses` list a guarantee rather
// than an exclusion.
const sharedSkillsDir = ".agents/skills"

// harnessesNotReadingSharedSkills is the whole of the fallback table: the
// harnesses known not to read the shared skills directory, which therefore need
// a copy in their own.
//
// It is empty in v1, and being empty is the finding rather than an omission —
// every harness on the roster reads `.agents/skills/`, which is what ADR 0002
// rests on. The table exists anyway, in exactly one place, because the survey
// behind that ADR will age: the day a harness is added that does not read the
// shared directory, this is the single edit, and a codebase that had encoded
// "everyone reads it" as an absence would need the rule discovered before it
// could be changed.
//
// A map rather than a slice so the lookup at the one call site reads as the
// question it asks.
var harnessesNotReadingSharedSkills = map[harness.ID]bool{}

// readsSharedSkills reports whether a harness finds a skill in the shared
// directory, which decides whether it also needs one of its own.
func readsSharedSkills(id harness.ID) bool {
	return !harnessesNotReadingSharedSkills[id]
}

// pathScopingKey is the frontmatter key by which a rule narrows what it applies
// to. Its presence is what makes a rule impossible to emulate as an
// instruction.
const pathScopingKey = "paths"

// targetPlan is where one asset lands for one harness, and on what terms.
//
// A plan is produced for every asset-and-target pairing, including the ones
// nothing will be written for: an unsupported pairing is an outcome the report
// has to carry, not a pairing to drop silently.
type targetPlan struct {
	// Harness is the target, and Scope the root Destination is relative to.
	Harness harness.ID
	Scope   manifest.Scope

	// Destination is relative to the scope root, slash-separated. It is empty
	// for an instruction, which lands inside the memory file's managed block
	// rather than at a path of its own.
	Destination string

	// Renderer is the transformation selected for this pairing, and Emulated
	// records that it reaches the harness through another type's surface.
	Renderer adapter.Renderer
	Emulated bool

	// Tier and Note carry the surface's terms into the report.
	Tier adapter.Tier
	Note string

	// Instruction marks a pairing that contributes to the memory file's block.
	Instruction bool

	// Unsupported is why nothing will be written, and is empty for a pairing
	// that will be. A reason rather than a bool, because every one of them
	// names a different next action for the reader.
	Unsupported string
}

// supported reports whether anything will be written for this pairing.
func (p targetPlan) supported() bool { return p.Unsupported == "" }

// declaresPathScoping reports whether a rule narrows itself to particular
// paths.
//
// It reads the frontmatter textually and decodes nothing, because the only
// question is whether the key is there — and a decoder would have to be handed
// a type, which would mean agreeing on a schema for a document harnaas
// deliberately never rewrites.
func declaresPathScoping(content []byte) bool {
	matter, found := source.SplitFrontmatter(content)
	if !found {
		return false
	}
	for _, line := range splitLinesKeepingEndings(matter.Raw) {
		if declaresKey(line, pathScopingKey) {
			return true
		}
	}
	return false
}

// planTarget decides where one asset lands for one harness.
//
// The order of the branches is the design's two-tier support: a skill and an
// instruction reach every harness through shared locations and never consult an
// adapter, and only the three types with no shared equivalent do. That is why
// "a harness with no adapter" is a supported state rather than a gap — it costs
// such a harness nothing for the two types most projects declare.
func planTarget(asset manifest.Asset, files []source.File, target harness.ID, registry *adapter.Registry) targetPlan {
	plan := targetPlan{Harness: target, Scope: asset.Scope, Renderer: adapter.RendererIdentity}
	if plan.Scope == "" {
		plan.Scope = manifest.ScopeProject
	}

	switch asset.Type {
	case manifest.AssetTypeSkill:
		if readsSharedSkills(target) {
			plan.Destination = path.Join(sharedSkillsDir, asset.ID)
			return plan
		}
		// Otherwise the skill needs a place in the harness's own directory,
		// which only a named adapter can say the location of, so the lookup
		// below runs as it does for the three per-harness types.

	case manifest.AssetTypeInstruction:
		// An instruction is inlined into the memory file's managed block, which
		// is one file for the whole project rather than one per asset, so it
		// has no destination of its own.
		plan.Instruction = true
		return plan

	case manifest.AssetTypeRule, manifest.AssetTypeCommand, manifest.AssetTypePersona:
	}

	adapted, err := registry.Lookup(target)
	if err != nil {
		plan.Unsupported = fmt.Sprintf(
			"%s has no harnaas adapter, and a %s reaches a harness only through one",
			target, asset.Type,
		)
		return plan
	}

	if destination, offered := adapted.Destination(asset); offered {
		return withSurface(plan, destination)
	}

	return emulate(plan, asset, files, adapted)
}

// withSurface fills a plan from the surface an adapter offered, refusing one the
// harness no longer reads.
//
// A removed surface is refused rather than written because writing there is a
// no-op that looks exactly like success — the file lands, the run is green, and
// the harness never opens it.
func withSurface(plan targetPlan, destination adapter.Destination) targetPlan {
	if destination.Tier == adapter.TierRemoved {
		plan.Unsupported = fmt.Sprintf(
			"%s no longer reads %s, so writing there would be a no-op that looks like success",
			plan.Harness, destination.Path,
		)
		if destination.Replacement != "" {
			plan.Unsupported += fmt.Sprintf(" (it reads %s instead)", destination.Replacement)
		}
		return plan
	}

	plan.Destination = destination.Path
	plan.Renderer = destination.Renderer
	plan.Tier = destination.Tier
	plan.Note = destination.Note
	return plan
}

// emulate decides whether an asset with no native surface can reach the harness
// through another type's, and refuses where doing so would change what the
// asset means.
//
// A native surface is always preferred, which is why this runs only after
// [adapter.Adapter.Destination] declined: emulation is the fallback, never a
// choice made while a real surface was available.
func emulate(plan targetPlan, asset manifest.Asset, files []source.File, adapted adapter.Adapter) targetPlan {
	switch asset.Type {
	case manifest.AssetTypeCommand:
		// A command delivered through the skill surface keeps its content and
		// loses only the harness's ability to start it unprompted, which the
		// renderer disables and the report states.
		if _, offered := adapted.Destination(skillAsset(asset)); !offered {
			plan.Unsupported = fmt.Sprintf("%s has no command surface and no skill surface to deliver one through", plan.Harness)
			return plan
		}
		plan.Destination = path.Join(sharedSkillsDir, asset.ID)
		plan.Renderer = adapter.RendererAsSkill
		plan.Emulated = true
		return plan

	case manifest.AssetTypeRule:
		if len(files) == 1 && declaresPathScoping(files[0].Content) {
			// Emulating this as an instruction would make a rule that applied
			// under some paths apply everywhere. That is a change of meaning
			// rather than of delivery, and it is invisible once written.
			plan.Unsupported = fmt.Sprintf(
				"%s has no rules directory, and this rule declares %q, "+
					"which the memory file cannot express: delivering it there would widen it from scoped to always-on",
				plan.Harness, pathScopingKey,
			)
			return plan
		}
		plan.Renderer = adapter.RendererAsInstruction
		plan.Emulated = true
		plan.Instruction = true
		return plan

	case manifest.AssetTypeSkill, manifest.AssetTypeInstruction, manifest.AssetTypePersona:
	}

	plan.Unsupported = fmt.Sprintf("%s has no surface for a %s and no way to deliver one without changing what it is",
		plan.Harness, asset.Type)
	return plan
}

// skillAsset is the asset as the skill surface would see it, used to ask an
// adapter whether it has one at all.
func skillAsset(asset manifest.Asset) manifest.Asset {
	asset.Type = manifest.AssetTypeSkill
	return asset
}

// declaredSource renders an asset reference the way the manifest spells it.
//
// The block in the memory file is committed, so a reader meeting text nobody on
// the team wrote needs the source in the form they would search harnaas.json
// for — not a normalized one that appears nowhere in the file they have open.
func declaredSource(ref manifest.AssetRef) string {
	if ref.Local() {
		return ref.Path
	}
	return ref.SourceKey + ":" + ref.Path
}

// Package harness is harnaas's roster of the harnesses it recognizes.
//
// The roster is data only: an id, a display name, whether the harness has an
// unambiguous per-user location, and the observable evidence that a project is
// already using it. It maps nothing to a destination and it writes nothing. The
// adapters that turn an asset into a file on disk arrive with `harnaas install`
// and attach themselves to these ids.
//
// That seam is deliberate. Three things in this change need to know a harness
// exists — manifest validation must reject an unrecognized target, scope
// validation must know whether `user` scope has anywhere to go, and `init` must
// detect which harnesses a project already uses — while none of them needs to
// know where a skill lands. Deferring the roster until the adapters exist would
// force the manifest to accept any string as a harness name and reject it two
// phases later, at a point where the error can no longer name the line that
// caused it.
//
// A harness in the manifest's `harnesses` list is a guarantee, not an
// observation: it means "we guarantee the declared assets work for this
// harness". Because skills and instructions land in shared locations that
// several harnesses read, a harness absent from the list will still see assets
// installed for one that is present. That is why an unrecognized name is an
// error — it is a guarantee harnaas cannot make — and why an asset being
// visible to a harness nobody listed is not.
package harness

// ID is a harness's canonical identifier: the exact string a manifest writes in
// its `harnesses` list or an asset's `targets`, and the key an adapter will
// later register itself under.
//
// It is a named type rather than a bare string so a function taking a harness
// cannot silently be handed an asset id, a source key or a display name.
type ID string

// ClaudeCode is the only harness this change recognizes. More arrive with the
// adapters; the roster is where they are declared, one entry each.
const ClaudeCode ID = "claude-code"

// Default is the harness `harnaas init` scaffolds a manifest with when it
// detects none in the project. A default is what keeps init from ever writing
// an empty `harnesses` list, which would be a manifest that declares assets and
// guarantees them for nothing.
const Default = ClaudeCode

// Harness describes one recognized harness. Every field is data a caller reads;
// there is no behaviour here, and adding some is how the roster and the
// adapters start to disagree.
type Harness struct {
	// ID is the canonical identifier, and the only spelling a manifest may
	// use. Display names are never accepted as input.
	ID ID

	// DisplayName is what harnaas prints when it names the harness to a user.
	// It is never parsed, and never compared against manifest input.
	DisplayName string

	// PerUserLocation records whether the harness reads assets from an
	// unambiguous location in the user's home as well as from the project.
	//
	// This is what decides whether an asset may declare `user` scope for this
	// target. It is a property of the harness, not a preference: where a
	// harness has no single per-user root, or several that disagree, harnaas
	// has no correct answer and says so rather than guessing one.
	PerUserLocation bool

	// ProjectEvidence lists the project-root-relative paths whose presence
	// means the project is already using this harness. Any one of them is
	// enough.
	//
	// Evidence is observable state in the repository, never configuration the
	// user has not written yet: `init` runs before harnaas knows anything about
	// the project, so the only thing it can read is what the harness itself has
	// already left behind. The entries are paths rather than a predicate
	// because the roster stays data — `init` does the stat calls.
	ProjectEvidence []string
}

// roster is every recognized harness, ordered by ID.
//
// The order is the one callers see, so it has to be a property of the data
// rather than of how the literal happens to be written — a manifest error
// listing recognized harnesses must read identically on every run and every
// machine. TestRosterIsOrderedByID pins it, so an entry added in the wrong
// place fails a test instead of quietly reordering somebody's error message.
var roster = []Harness{
	{
		ID:              ClaudeCode,
		DisplayName:     "Claude Code",
		PerUserLocation: true,
		ProjectEvidence: []string{".claude", "CLAUDE.md"},
	},
}

package adapter

import (
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Registry is the set of named adapters this binary can install through, keyed
// by the harness each one addresses.
//
// A registry value rather than one package-level map is what lets a test
// exercise lookup — including the failure for a harness nobody wrote an adapter
// for — without reaching into the set the binary itself ships.
type Registry struct {
	mu sync.Mutex

	// adapters holds each adapter as a value rather than a constructor, which is
	// deliberately unlike the source-kind registry: a kind remembers which
	// archives this run has already fetched and so belongs to the run, while an
	// adapter is a mapping from an asset to a path and has nothing to remember.
	// Handing every run its own copy of a pure mapping would suggest it did.
	adapters map[harness.ID]Adapter
}

// Default is the registry the adapters shipped with this binary register into,
// and the one the install flow resolves destinations through. An adapter package
// registers itself from its own init, so an adapter that has been linked in is an
// adapter that works.
var Default = &Registry{}

// Register adds an adapter to [Default].
func Register(adapter Adapter) {
	Default.Register(adapter)
}

// Register adds an adapter under the harness it addresses.
//
// A second adapter for one harness panics rather than replacing or ignoring the
// first. Registration happens during package initialization, before the process
// has read anything, so the only way to reach it is a mistake in harnaas's own
// wiring — and both silent outcomes are a binary that installs through whichever
// adapter happened to be linked last.
func (r *Registry) Register(adapter Adapter) {
	id := adapter.Harness()

	r.mu.Lock()
	defer r.mu.Unlock()

	if r.adapters == nil {
		r.adapters = make(map[harness.ID]Adapter)
	}
	if _, registered := r.adapters[id]; registered {
		panic(fmt.Sprintf("adapter: harness %q has two adapters registered", id))
	}
	r.adapters[id] = adapter
}

// Lookup returns the adapter for a harness.
//
// A harness with no adapter is not a broken install by itself: skills and
// instructions reach every harness through shared locations, and this lookup only
// happens for the types that have no shared equivalent. That is why the failure
// is a typed diagnostic the caller can attribute to the asset that needed it,
// rather than something the registry decides is fatal.
func (r *Registry) Lookup(id harness.ID) (Adapter, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	adapter, registered := r.adapters[id]
	if !registered {
		return nil, &NotRegisteredError{Harness: id, Registered: r.harnessesLocked()}
	}
	return adapter, nil
}

// Registered reports whether a harness has a named adapter.
//
// It is separate from [Registry.Lookup] because the install flow asks the
// question long before it has an asset to blame for the answer: a harness with no
// adapter still installs every shared asset, and building a diagnostic to throw
// away would be the wrong shape for that path.
func (r *Registry) Registered(id harness.ID) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	_, registered := r.adapters[id]
	return registered
}

// Harnesses returns every harness with a named adapter, sorted.
//
// Sorted rather than in registration order, because registration order is
// whatever the import graph happens to produce and this list is rendered into the
// message a user reads when their harness is not among them.
func (r *Registry) Harnesses() []harness.ID {
	r.mu.Lock()
	defer r.mu.Unlock()

	return r.harnessesLocked()
}

// Adapters returns every registered adapter, in [Registry.Harnesses] order, so a
// caller that walks them reports the same thing on every run.
func (r *Registry) Adapters() []Adapter {
	r.mu.Lock()
	defer r.mu.Unlock()

	adapters := make([]Adapter, 0, len(r.adapters))
	for _, id := range r.harnessesLocked() {
		adapters = append(adapters, r.adapters[id])
	}
	return adapters
}

// harnessesLocked returns the registered harnesses in sorted order. The caller
// holds the lock.
func (r *Registry) harnessesLocked() []harness.ID {
	ids := make([]harness.ID, 0, len(r.adapters))
	for id := range r.adapters {
		ids = append(ids, id)
	}
	slices.Sort(ids)
	return ids
}

// NotRegisteredError reports a harness this binary has no named adapter for.
//
// The manifest layer has already accepted the name, because the roster
// recognizes more harnesses than there are adapters and that is the intended
// state: a harness harnaas knows about receives every shared asset without one.
// So the problem is never "this harness does not exist" — it is that the asset in
// hand is of a type with no shared equivalent, and the message has to say which
// harnesses could have taken it.
type NotRegisteredError struct {
	// Harness is the harness with no adapter, exactly as the manifest wrote it.
	Harness harness.ID

	// Registered is every harness this binary has an adapter for, sorted.
	Registered []harness.ID
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *NotRegisteredError) Error() string {
	return fmt.Sprintf(
		"harnaas has no adapter for the harness %q, and a %s, %s or %s asset has no shared location to install to\n\n"+
			"%s Skills and instructions need no adapter and install for every harness harnaas recognizes.",
		e.Harness,
		manifest.AssetTypeRule, manifest.AssetTypeCommand, manifest.AssetTypePersona,
		e.remedy(),
	)
}

// remedy names the harnesses that would have worked, or says plainly that there
// are none. An empty registry is unreachable from a built binary — it links at
// least one adapter — but a message reading "target one of: ." is worse than one
// stating the situation.
func (e *NotRegisteredError) remedy() string {
	if len(e.Registered) == 0 {
		return fmt.Sprintf("This harnaas has no adapters at all, so remove the entry from %s.", manifest.FileName)
	}

	names := make([]string, 0, len(e.Registered))
	for _, id := range e.Registered {
		names = append(names, fmt.Sprintf("%q", id))
	}

	return fmt.Sprintf(
		"Change the entry's %q in %s to a harness harnaas has an adapter for: %s.",
		"targets", manifest.FileName, strings.Join(names, ", "),
	)
}

package adapter

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// ResolveRoot returns the harness directory an asset installs beneath: the
// adapter's own root for the asset's scope, relative to that scope's own root —
// the project root at `project` scope, the user's home at `user` scope.
//
// Which scope an asset has is settled long before this: [manifest.Interpret]
// defaults an undeclared one to `project`, refuses a scope harnaas does not
// define, and refuses `user` where the *roster* records no per-user location.
// What is left for this layer is the question only an adapter can answer — does
// this harness have an unambiguous location for that scope — and the roster's
// answer is deliberately not taken as this one. The roster is a fact about a
// harness the manifest layer can check without linking a single adapter; the
// adapter is the thing that actually knows its own directories, and where the
// two disagree the adapter is right.
//
// A refusal is a refusal, never a quieter install: an asset that asked for
// `user` scope and was given the project root would be installed somewhere its
// author did not ask for, in a file they would have no reason to look at.
func ResolveRoot(a Adapter, asset manifest.Asset) (string, error) {
	scope := asset.Scope
	if scope == "" {
		// An Asset always carries a scope, because Interpret is the only route
		// to one and it defaults an undeclared field. The restatement is not a
		// second place the default is decided — it is what stops a zero value
		// reaching a.Root("") and producing a diagnostic about a scope nobody
		// wrote.
		scope = manifest.ScopeProject
	}

	root, offered := a.Root(scope)
	if !offered {
		return "", &UnsupportedScopeError{
			AssetID: asset.ID,
			Type:    asset.Type,
			Harness: a.Harness(),
			Scope:   scope,
		}
	}

	return root, nil
}

// UnsupportedScopeError reports an asset whose scope this harness has no
// unambiguous directory for.
//
// It names the asset and the harness because the pairing is what is wrong:
// `user` scope is correct for the asset and the harness is correct for the
// project, and only together do they name a location harnaas would have to
// invent. Inventing one is the outcome this refusal exists to prevent — an
// asset installed under a guessed per-user directory reports success, is never
// read, and leaves the team believing it is in effect.
type UnsupportedScopeError struct {
	// AssetID is the asset that asked for the scope.
	AssetID string

	// Type is the asset's type, which is how the message names it in the
	// author's own vocabulary rather than as "the asset".
	Type manifest.AssetType

	// Harness is the harness with no directory for that scope.
	Harness harness.ID

	// Scope is the scope that could not be resolved.
	Scope manifest.Scope
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnsupportedScopeError) Error() string {
	return fmt.Sprintf(
		"the %s %q installs at %q scope, and the harness %q has no unambiguous location for that scope\n\n"+
			"%s",
		e.Type, e.AssetID, e.Scope, e.Harness,
		e.remedy(),
	)
}

// remedy names the edit that fixes it, which depends on which scope was asked
// for. Dropping the scope is an edit only where there is a scope to drop: at
// `project` scope there is nothing to remove and the entry's only route to a
// harness that can take it is its `targets`.
func (e *UnsupportedScopeError) remedy() string {
	if e.Scope == manifest.ScopeUser {
		return fmt.Sprintf(
			"Remove %q from the entry in %s so it installs at %q scope, or narrow the entry's %q to harnesses with a per-user location.",
			"scope", manifest.FileName, manifest.ScopeProject, "targets",
		)
	}

	return fmt.Sprintf(
		"Remove %q from the entry's %q in %s.",
		e.Harness, "targets", manifest.FileName,
	)
}

// Package adapter is where an asset lands on one named harness.
//
// Most harnesses need no adapter at all. Of the harnesses surveyed for this
// design, 17 read `.agents/skills/<id>/SKILL.md` and 21 read `AGENTS.md`, so a
// skill and an instruction reach them through shared locations that no
// per-harness code computes. What has no shared equivalent anywhere is a rule, a
// command and a persona, and those reach a harness only through an adapter that
// knows its directories. Version 1 ships exactly one, `claude-code`, and "a
// harness with no adapter" is a supported state rather than a gap.
//
// This package is the contract and the registry; each adapter is its own package
// beneath it. The split is the extraction rule doing its work rather than a layer
// for its own sake: the install flow lives in the flat cli package and has to
// import the adapters, so an adapter importing a contract that lived beside the
// flow would be an import cycle one file later. Keeping the contract here is also
// what makes the import boundary checkable — an adapter may reach this package
// and general-purpose utilities, and nothing else.
//
// An adapter answers questions and performs no I/O of its own. It is handed a
// filesystem to detect through and it returns paths for the caller to write, for
// the same reason the harness roster holds no behaviour: two things that can each
// compute a destination eventually compute two different ones.
package adapter

import (
	"io/fs"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Adapter maps assets onto the files one harness reads.
//
// The contract is uniform on purpose: the install flow obtains a destination
// without knowing which harness it is addressing, so adding the second adapter
// is additive rather than another branch in the flow.
type Adapter interface {
	// Harness is the identity this adapter registers under, and the exact
	// string a manifest writes in `harnesses` or in an asset's `targets`.
	Harness() harness.ID

	// Detect reports whether the project already shows evidence of this
	// harness — its configuration directory existing, or a file only it
	// writes.
	//
	// The parameter is a filesystem rather than a directory path because
	// detection must create nothing: an fs.FS offers no way to write, so
	// "detection has no side effects" is a property of the signature rather
	// than a rule each adapter has to honour. A harness that is simply not
	// installed is an absence and never a failure — there is nothing for a
	// caller to do about it and nothing to report.
	Detect(project fs.FS) bool

	// Root returns the harness's own directory for one scope, relative to that
	// scope's root: the project root at `project` scope, and the user's home
	// directory at `user` scope. The second result is false where the harness
	// has no unambiguous location for that scope, which is the whole of the
	// adapter's answer to whether an asset may declare it.
	//
	// It is relative, and joined by the caller, because an adapter that read
	// the environment for a home directory would be a second place in harnaas
	// deciding where a user's files live.
	Root(scope manifest.Scope) (string, bool)

	// Destination returns where one asset installs on this harness, relative to
	// the resolved scope root — the harness's own directory for the asset's
	// scope, which is [Adapter.Root] joined to the project root or to the
	// user's home. A rule resolves to `rules/house-style.md` there, never to a
	// path counted from the project root, so the same mapping serves both
	// scopes and the lockfile can record a destination that means the same
	// thing on another machine.
	//
	// The second result is false where this harness has no surface for the
	// asset's type. That absence is a value rather than an invented path
	// precisely because a guessed destination is indistinguishable from a real
	// one once it is written: the caller reports the pairing as unsupported and
	// installs the asset's other targets.
	//
	// The asset travels whole rather than as the type, id and scope a mapping
	// reads, for the reason a source request does: the fields a diagnostic needs
	// are not the fields the mapping needs, and narrowing the parameter would
	// make every caller's messages worse to keep a signature shorter.
	Destination(asset manifest.Asset) (Destination, bool)
}

// Destination is where one asset installs on one harness, together with the
// terms it installs on.
//
// The terms travel with the path because they are decided by the same lookup:
// which surface a type maps to is what settles how current that surface is and
// what has to happen to the bytes on their way into it. Splitting them would let
// a caller obtain a path and write it without ever asking whether the harness
// still reads there.
type Destination struct {
	// Path is the installed file relative to the resolved scope root,
	// slash-separated. Whether it stays inside that root is not this value's
	// promise: the write goes through a handle anchored there, so an asset id
	// that would escape is refused by the kernel at the moment of the write
	// rather than by a comparison at the moment it was computed.
	Path string

	// Tier is how current the surface is, which decides whether harnaas writes
	// here at all.
	Tier Tier

	// Replacement names the surface that superseded a removed one, and is set
	// only where Tier is [TierRemoved]. It is what makes the refusal actionable:
	// the reader is being told the harness stopped reading this path, and the
	// only useful next sentence is where it reads instead.
	Replacement string

	// Note is the sentence the install report carries for a gated or a legacy
	// surface — the setup the user still has to perform, or the deprecation
	// they should plan for. A live surface carries none, because a note nobody
	// has to act on teaches a reader to skip them all.
	Note string

	// Renderer names the transformation from the source's bytes to the ones
	// that land here. It is a name rather than a function because an adapter
	// declares what a surface needs while the rendering layer owns how it is
	// done: an adapter carrying an implementation would import the layer the
	// import boundary exists to keep out.
	Renderer Renderer
}

// Tier is how current a harness surface is, which decides whether harnaas writes
// to it.
//
// It exists because a harness that has moved on from a path does not say so: the
// write succeeds, the file appears, and nothing ever reads it. That is the exact
// outcome a tool whose purpose is telling a team what is in effect must not
// produce, so the state of a surface is data harnaas carries rather than
// something a user discovers.
type Tier string

const (
	// TierLive is a surface the harness reads today. It is written with no
	// note, which is what keeps the notes on the other tiers worth reading.
	TierLive Tier = "live"

	// TierGated is a surface the harness reads only once the user has enabled
	// something. It is written, with the setup note carried into the install
	// report, because the file is correct and the remaining step is theirs.
	TierGated Tier = "gated"

	// TierLegacy is a surface the harness still reads but has deprecated. It is
	// written, with the deprecation note carried into the report, so a team
	// learns before the surface becomes removed rather than after.
	TierLegacy Tier = "legacy"

	// TierRemoved is a surface the harness no longer reads. Writing there is a
	// guaranteed silent no-op, so it is refused rather than written, naming the
	// surface that replaced it.
	TierRemoved Tier = "removed"
)

// Renderer names the transformation between a source's bytes and the bytes that
// land at a destination.
//
// A name rather than a function keeps the adapter layer and the rendering layer
// apart, and it is also what makes a surface able to declare a renderer nobody
// has written yet: selecting one with no implementation reports the pairing
// unsupported and names the renderer, which is a truthful outcome, where falling
// back to copying the bytes would write a file the harness cannot read.
type Renderer string

const (
	// RendererIdentity reproduces the source bytes exactly, including
	// frontmatter, line endings and trailing whitespace. It is what almost
	// every surface declares, and it is deliberately a renderer rather than the
	// absence of one: copying is the default, not the rule.
	RendererIdentity Renderer = "identity"

	// RendererAsSkill delivers an asset through a harness's skill surface when
	// its own surface is absent — a command as a SKILL.md the model is told not
	// to invoke on its own initiative. It is an emulation, and is reported as
	// one rather than as plain success.
	RendererAsSkill Renderer = "as-skill"

	// RendererAsInstruction delivers a rule through the memory file's managed
	// block on a harness with no rules directory. It is an emulation, and it is
	// only ever selected for a rule that declares no path scoping: a scoped
	// rule delivered this way would silently become always-on, which is a
	// change of meaning rather than of delivery.
	RendererAsInstruction Renderer = "as-instruction"

	// RendererMDC converts an asset into Cursor's `.mdc` rule format.
	//
	// It is named and deliberately not implemented in v1. Naming it is the
	// point: a surface added later may declare it before anybody writes it, and
	// the pairing is then reported unsupported and names this renderer, rather
	// than falling back to copying bytes into a file the harness cannot read.
	// This is the constant that keeps that path exercised while v1 ships one
	// adapter whose every surface renders identically.
	RendererMDC Renderer = "mdc"
)

// Renderers returns every renderer the contract names, implemented or not, in a
// fixed order.
//
// The set is declared here rather than derived from what the rendering layer
// happens to implement, because the two answer different questions: this is
// what an adapter may declare, and the rendering layer decides what harnaas can
// actually produce. A name missing from here is a surface no adapter can point
// at; a name here with no implementation is the supported "unsupported" case.
func Renderers() []Renderer {
	return []Renderer{RendererIdentity, RendererAsSkill, RendererAsInstruction, RendererMDC}
}

// Package claudecode maps assets onto the files Claude Code reads.
//
// It is version 1's only named adapter, and it exists for the three asset types
// that have no shared equivalent anywhere: a rule, a command and a persona. A
// skill and an instruction reach Claude Code the way they reach every other
// harness — through `.agents/skills/` and the project's memory file — so they
// are deliberately absent from the mapping here rather than mapped a second
// time into `.claude/`. An adapter that answered for them would be a second
// place harnaas decides where a skill lands, and the two answers would be one
// release from disagreeing.
//
// Everything this package knows is a question the contract asks: which harness
// it registers under, whether the project already uses it, its own directory per
// scope, and the destination for one asset. It performs no I/O, holds no state
// and reads no environment, so linking it changes what harnaas can install and
// nothing else.
package claudecode

import (
	"io/fs"
	"path"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/adapter"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// init registers this adapter with [adapter.Default], so a binary that links
// this package is a binary that can install a rule, a command or a persona for
// Claude Code. Registration lives here rather than in the install flow for the
// reason a source kind's does: a list maintained elsewhere is a list a new
// adapter has to remember to join, and the failure that produces is an adapter
// which compiles, passes its own tests and is missing from the registry.
//
//nolint:gochecknoinits // Self-registration is the adapter contract; see [adapter.Registry].
func init() {
	adapter.Register(New())
}

// directory is Claude Code's own directory, relative to the root of whichever
// scope an asset installs at: `<project>/.claude` and `<home>/.claude`.
//
// That both scopes spell it the same way is a fact about this harness and not a
// rule — the contract returns a root per scope precisely because another harness
// will not — so [Adapter.Root] answers per scope rather than returning one
// constant to both callers.
const directory = ".claude"

// extension is the file extension every Claude Code surface takes. The asset id
// is the stem, which is what makes a destination predictable from the manifest
// alone: an author reading `rules/house-style.md` in the report can find the
// entry that produced it without consulting the lockfile.
const extension = ".md"

// surfaces is the whole of Claude Code's mapping: the directory beneath the
// resolved scope root for each asset type this harness has a surface for,
// together with the terms that surface installs on.
//
// A type absent from this table is a type Claude Code has no surface for, which
// is the answer [Adapter.Destination] returns rather than an invented path. Both
// absences here are deliberate and neither is a gap: a skill and an instruction
// install through shared locations, and the install flow consults a named
// adapter only for the types that have none.
//
// Every surface is live today. The tier travels anyway, because a harness that
// stops reading a path does not announce it — the day one of these becomes
// legacy or removed, the edit is one field in this table and the install report
// changes with it.
var surfaces = map[manifest.AssetType]adapter.Destination{
	manifest.AssetTypeRule: {
		Path:     "rules",
		Tier:     adapter.TierLive,
		Renderer: adapter.RendererIdentity,
	},
	manifest.AssetTypeCommand: {
		Path:     "commands",
		Tier:     adapter.TierLive,
		Renderer: adapter.RendererIdentity,
	},
	manifest.AssetTypePersona: {
		Path:     "agents",
		Tier:     adapter.TierLive,
		Renderer: adapter.RendererIdentity,
	},
}

// Adapter installs assets for Claude Code.
//
// It holds nothing. An adapter is a mapping from an asset to a path, and this
// one is registered as a value for that reason: there is no per-run state to
// give each run its own copy of.
type Adapter struct{}

var _ adapter.Adapter = Adapter{}

// New returns the claude-code adapter.
func New() Adapter { return Adapter{} }

// Harness is the identity this adapter registers under, and the exact string a
// manifest writes.
func (Adapter) Harness() harness.ID { return harness.ClaudeCode }

// Detect reports whether the project already shows evidence of Claude Code.
//
// The evidence is the roster's rather than a second list kept here. `init`
// detects harnesses to scaffold a manifest and this adapter detects one to
// report on an install, and the two answering differently for one project is
// exactly the drift that keeps the roster behaviourless — so there is one
// declaration of what counts as evidence, and both readers read it.
func (Adapter) Detect(project fs.FS) bool {
	h, err := harness.Lookup(harness.ClaudeCode)
	if err != nil {
		// Unreachable from the shipped roster, which is what registration is
		// keyed on. A roster that had lost this harness would leave harnaas
		// unable to accept `claude-code` in a manifest at all, so reporting
		// absence is the only answer detection could usefully give.
		return false
	}

	return detect(project, h.ProjectEvidence)
}

// detect reports whether any one of the evidence paths is present. Any single
// piece is enough: a project with a `CLAUDE.md` and no `.claude/` is still a
// project using Claude Code.
//
// The check is an Lstat rather than a Stat, matching init's rule for the same
// reason — the question is whether the harness left something behind, not
// whether it resolves. A `.claude` symbolic link into a directory that is not
// checked out is still evidence, and following it would answer "no" for a
// project that plainly says yes.
func detect(project fs.FS, evidence []string) bool {
	for _, name := range evidence {
		if _, err := fs.Lstat(project, name); err == nil {
			return true
		}
	}
	return false
}

// Root returns Claude Code's own directory for one scope, relative to that
// scope's root.
//
// Both scopes are offered, and that is the harness's own property rather than a
// convenience: Claude Code reads `<home>/.claude` unambiguously, which is what
// lets an asset declare `user` scope for this target at all. A harness whose
// per-user location were ambiguous would return false here, and
// [adapter.ResolveRoot] would refuse the asset rather than quietly installing it
// at project scope.
func (Adapter) Root(scope manifest.Scope) (string, bool) {
	switch scope {
	case manifest.ScopeProject, manifest.ScopeUser:
		return directory, true
	default:
		return "", false
	}
}

// Destination returns where one asset installs on Claude Code, relative to the
// resolved scope root: a rule at `rules/<id>.md`, a command at
// `commands/<id>.md` and a persona at `agents/<id>.md`.
//
// The scope does not enter the mapping. It selects the root the path is joined
// beneath, and whether the harness has a root for it is [Adapter.Root]'s answer,
// asked once by [adapter.ResolveRoot] before any destination is wanted — so the
// same relative path serves both scopes and the lockfile records something that
// means the same thing on another machine.
//
// A rule installs as a standalone file the harness discovers on its own.
// Nothing references it from `CLAUDE.md`, from `AGENTS.md` or from any managed
// block, which is a property of this mapping being the whole of what a rule
// needs: adding a reference would put the same fact in two files and leave the
// second one to rot.
func (Adapter) Destination(asset manifest.Asset) (adapter.Destination, bool) {
	surface, supported := surfaces[asset.Type]
	if !supported {
		return adapter.Destination{}, false
	}

	surface.Path = path.Join(surface.Path, asset.ID+extension)
	return surface, true
}

package cli

import (
	"bytes"
	"cmp"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// memoryFileName is the project's committed memory file — the file a harness
// reads for always-on guidance without anybody having run install.
//
// `AGENTS.md` rather than any harness's own file: it is the one memory file
// several harnesses already read, and the harness whose file it is not reaches
// it through a bridge line. That is also what makes an instruction distinct
// from a rule at all — an instruction survives a fresh clone because it lives
// in a committed file, and a rule does not because it lives in an installed
// one.
const memoryFileName = "AGENTS.md"

// instructionBlock is the region harnaas owns inside the memory file.
//
// The markers are HTML comments because the memory file is Markdown, where they
// render as nothing. The name in them is `instructions` rather than a bare
// `harnaas`, because the ignore file's block is harnaas's too and a reader
// meeting one marker should not have to know which of harnaas's blocks it
// delimits.
var instructionBlock = managedBlock{
	file:  memoryFileName,
	begin: "<!-- harnaas:begin instructions -->",
	end:   "<!-- harnaas:end instructions -->",
}

// instruction is one instruction asset's contribution to the memory file.
//
// It carries the source alongside the content because the block is committed:
// a reader opening `AGENTS.md` months later meets text nobody on the team
// wrote, and the comment above it is the only thing in the file that says where
// it came from.
type instruction struct {
	// ID is the asset's id, which is what the block is ordered by.
	ID string

	// Source is the asset's source spelled the way the manifest declares it.
	Source string

	// Content is the asset's bytes, inlined verbatim.
	Content []byte
}

// renderInstructionBlock is the body of the memory file's managed block.
//
// The ordering is by asset id and not by manifest position, so moving an entry
// in `harnaas.json` regenerates a byte-identical block: the manifest's order
// says nothing about what the assets mean, and a diff that moved a thousand
// lines because somebody sorted their manifest would be a diff nobody reads.
//
// Content is inlined verbatim. The one byte that may be added is a newline
// after content that does not end in one, because the next asset's comment has
// to begin a line — every other byte of every asset arrives in the file exactly
// as it resolved.
func renderInstructionBlock(instructions []instruction) []byte {
	ordered := slices.Clone(instructions)
	slices.SortStableFunc(ordered, func(a, b instruction) int {
		return cmp.Compare(a.ID, b.ID)
	})

	var body bytes.Buffer
	for i, entry := range ordered {
		if i > 0 {
			body.WriteByte('\n')
		}
		fmt.Fprintf(&body, "<!-- harnaas instruction %q from %s -->\n", entry.ID, entry.Source)
		body.Write(entry.Content)
		if len(entry.Content) > 0 && entry.Content[len(entry.Content)-1] != '\n' {
			body.WriteByte('\n')
		}
	}

	return body.Bytes()
}

// writeInstructionBlock makes the memory file's managed block hold exactly
// these instruction assets, and removes the block when there are none.
//
// The empty case is a removal rather than an empty block on purpose: a block
// with nothing in it is a claim that harnaas has something to say here, and the
// state after the last instruction asset goes is that it does not.
func writeInstructionBlock(root string, instructions []instruction) error {
	if len(instructions) == 0 {
		return dropManagedBlock(root, instructionBlock)
	}
	return writeManagedBlock(root, instructionBlock, renderInstructionBlock(instructions))
}

// bridgeFileName is the file the bridge line lives in, and bridgeLine is the
// line itself.
//
// Claude Code does not read `AGENTS.md` at all, so the instruction block would
// be invisible to it without one line importing the file. Every other harness
// on the roster reads `AGENTS.md` directly and needs nothing.
//
// This is a single line rather than a managed block because it is a single
// line: a pair of markers around one import would be three lines of harnaas in
// a file the team writes, to own what a whole-line match already identifies.
const (
	bridgeFileName = "CLAUDE.md"
	bridgeLine     = "@" + memoryFileName
)

// matchesBridgeLine reports whether a line is the bridge.
//
// The line arrives with its ending still attached, because the caller splits
// without discarding one, so the newline is trimmed here alongside the trailing
// whitespace and carriage return that [matchesMarker] ignores for the same
// reason: a file edited on another platform is the same file.
//
// Leading whitespace is not trimmed — an indented `@AGENTS.md` is inside
// somebody's list or code fence, where it is prose about the import rather than
// the import, and harnaas neither counts it nor removes it.
func matchesBridgeLine(line string) bool {
	return strings.TrimRight(line, " \t\r\n") == bridgeLine
}

// setBridgeLine makes content carry exactly one bridge line.
//
// Where there is none, it is appended at the end, after a newline if the file
// did not end in one — an import that shares a line with the last sentence of
// the file is not an import. Where there is exactly one, wherever it sits, the
// content is returned untouched: the line works from anywhere, and moving it to
// the end would be harnaas editing a file to satisfy nothing but its own idea
// of where the line belongs.
//
// Where there are several, the first is kept and the rest are dropped. The
// first is where the author put it; the duplicates are what a re-run of an
// older harnaas, or a merge, left behind.
func setBridgeLine(content []byte) []byte {
	lines := splitLinesKeepingEndings(content)

	seen := false
	kept := make([][]byte, 0, len(lines))
	for _, line := range lines {
		if matchesBridgeLine(string(line)) {
			if seen {
				continue
			}
			seen = true
		}
		kept = append(kept, line)
	}

	if seen {
		return bytes.Join(kept, nil)
	}

	updated := bytes.Join(kept, nil)
	if len(updated) > 0 && updated[len(updated)-1] != '\n' {
		updated = append(updated, '\n')
	}
	return append(updated, bridgeLine...)
}

// clearBridgeLine removes every bridge line from content, and reports whether
// what is left is worth keeping as a file.
//
// "Nothing else" is read as nothing but whitespace. A file harnaas created
// holds the bridge line and a newline, and a file somebody added a blank line
// to is still a file whose only content was the bridge — but a file with a
// sentence in it is theirs, and it stays even when the bridge is gone.
func clearBridgeLine(content []byte) (remainder []byte, empty bool) {
	lines := splitLinesKeepingEndings(content)

	kept := make([][]byte, 0, len(lines))
	for _, line := range lines {
		if matchesBridgeLine(string(line)) {
			continue
		}
		kept = append(kept, line)
	}

	remainder = bytes.Join(kept, nil)
	return remainder, len(bytes.TrimSpace(remainder)) == 0
}

// splitLinesKeepingEndings splits content into lines with their line endings
// still attached, so joining them reproduces the input byte for byte.
//
// bytes.Split would discard the information needed to tell a file that ends in
// a newline from one that does not, and rebuilding with a fixed separator would
// rewrite every CRLF in a file harnaas was asked to add one line to.
func splitLinesKeepingEndings(content []byte) [][]byte {
	var lines [][]byte
	for len(content) > 0 {
		end := bytes.IndexByte(content, '\n')
		if end < 0 {
			lines = append(lines, content)
			break
		}
		lines = append(lines, content[:end+1])
		content = content[end+1:]
	}
	return lines
}

// writeBridgeLine ensures CLAUDE.md imports the memory file, creating it
// holding only that line when it is absent.
func writeBridgeLine(root string) error {
	content, err := readManagedFile(root, bridgeFileName)
	if err != nil {
		return err
	}

	updated := setBridgeLine(content)
	if bytes.Equal(updated, content) {
		return nil
	}

	return writeManagedFile(root, bridgeFileName, updated)
}

// dropBridgeLine removes the bridge line, and removes CLAUDE.md itself when the
// line was all it held.
//
// Deleting the file is what keeps a full uninstall from leaving a file behind
// that harnaas created and nobody wrote. It is bounded to the case where
// nothing but whitespace remains, because every other case is somebody's file
// that happened to import the memory file.
func dropBridgeLine(root string) error {
	content, err := readManagedFile(root, bridgeFileName)
	if err != nil {
		return err
	}
	if len(content) == 0 {
		return nil
	}

	remainder, empty := clearBridgeLine(content)
	if bytes.Equal(remainder, content) {
		return nil
	}

	if empty {
		if err := os.Remove(filepath.Join(root, bridgeFileName)); err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("remove %s: %w", bridgeFileName, err)
		}
		return nil
	}

	return writeManagedFile(root, bridgeFileName, remainder)
}

